impl From<(crate::Tense, crate::Polarity, crate::Person)> for Cell {
    fn from((tense, polarity, person): (crate::Tense, crate::Polarity, crate::Person)) -> Self {
        Cell::Indicative(tense, polarity, person)
    }
}

impl From<(crate::Polarity, crate::ImperativePerson)> for Cell {
    fn from((polarity, imperative_person): (crate::Polarity, crate::ImperativePerson)) -> Self {
        Cell::Imperative(polarity, imperative_person)
    }
}

impl From<(crate::Polarity, crate::PerfectImperativePerson)> for Cell {
    fn from(
        (polarity, perfect_imperative_person): (crate::Polarity, crate::PerfectImperativePerson),
    ) -> Self {
        Cell::PerfectImperative(polarity, perfect_imperative_person)
    }
}

impl From<crate::Voice> for Cell {
    fn from(voice: crate::Voice) -> Self {
        Cell::SecondInfinitive(voice)
    }
}

impl From<crate::ThirdCase> for Cell {
    fn from(third_case: crate::ThirdCase) -> Self {
        Cell::ThirdInfinitive(third_case)
    }
}

impl From<crate::Participle> for Cell {
    fn from(participle: crate::Participle) -> Self {
        Cell::Participle(participle)
    }
}

/// A verb to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Verb<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
}

impl<'w> Verb<'w> {
    /// The verb `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Verb {
            lemma,
            given: Vec::new(),
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    fn known(&self) -> Known<'_> {
        Known {
            forms: &self.given,
            inherent: &[],
            full: false,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The conjugations it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn conjugation(&self) -> Vec<Reading<'static, 'static, Conjugation>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
